        "code": "import html\nfrom urllib.parse import urlsplit\n\nSAFE_SCHEMES = {\"http\", \"https\"}\n\n\ndef render_profile_vulnerable(name, website):\n    # VULNERABLE: raw values in an HTML body and in an attribute\n    return f'<h2>{name}</h2><a href=\"{website}\">My website</a>'\n\n\ndef safe_url(url):\n    # Encoding does not stop javascript: URLs, so the scheme goes through an allow-list\n    return url if urlsplit(url).scheme.lower() in SAFE_SCHEMES else \"#\"\n\n\ndef render_profile(name, website):\n    # FIXED: html.escape() encodes & < > and, with quote=True (the default), \" and '\n    return (f\"<h2>{html.escape(name)}</h2>\"\n            f'<a href=\"{html.escape(safe_url(website))}\">My website</a>')\n\n\nattacks = [\n    (\"<script>alert(1)</script>\", \"https://example.com\"),\n    (\"Bob\", 'https://example.com/\" onmouseover=\"alert(1)'),\n    (\"Bob\", \"javascript:alert(document.cookie)\"),\n]\n\nfor name, website in attacks:\n    print(\"vulnerable:\", render_profile_vulnerable(name, website))\n    print(\"fixed     :\", render_profile(name, website))\n    print()\n",
